#!/usr/bin/env python3
"""Generate self-hosted font subsets for the robin-blue v6 UI."""
import io
import pathlib
import urllib.request
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent  # app/
CLIENT = ROOT / "client"
OUT = CLIENT / "public" / "fonts"
TMP = pathlib.Path("/tmp/v6fonts")

SOURCES = {
    "cormorant-garamond-sub.woff2": (
        "https://cdn.jsdelivr.net/gh/google/fonts@main/ofl/cormorantgaramond/CormorantGaramond%5Bwght%5D.ttf",
        "Cormorant Garamond",
    ),
    "noto-sans-sc-sub.woff2": (
        "https://cdn.jsdelivr.net/gh/google/fonts@main/ofl/notosanssc/NotoSansSC%5Bwght%5D.ttf",
        "Noto Sans SC",
    ),
}
# Noto Serif SC 的可变字体超过 jsDelivr 单文件 20MB 限制（403），
# 改用 npm 包 @expo-google-fonts/noto-serif-sc 的静态字重：
#   npm pack @expo-google-fonts/noto-serif-sc
#   pyftsubset package/500Medium/NotoSerifSC_500Medium.ttf -> noto-serif-sc-500.woff2
#   pyftsubset package/600SemiBold/NotoSerifSC_600SemiBold.ttf -> noto-serif-sc-600.woff2
#（500/600 两档对应 styles.css 中 serif 的全部字重）

